tration</h1><p class="font-body-md text-base text-[#736360] mt-2 max-w-sm">Sign in to manage shelter operations and staff credentials.</p></div><form class="flex flex-col gap-5" id="authForm" novalidate="" onsubmit="event.preventDefault(); triggerAuth();"><div class="flex flex-col gap-2 text-left"><div class="flex items-center justify-between"><label class="font-label-md text-sm uppercase tracking-wider text-[#221B1A] font-semibold" for="adminEmail">Email Address</label></div><div class="relative flex items-center bg-white border border-[#E3DBD5] rounded-xl focus-within:border-[#E05A4F] focus-within:ring-2 focus-within:ring-[#E05A4F]/20 transition-all"><div class="absolute left-4 text-[#E05A4F] flex items-center pointer-events-none"><span class="material-symbols-outlined text-[22px]">alternate_email</span></div><input class="w-full h-14 pl-12 pr-4 text-[#221B1A] bg-transparent font-body-md text-base placeholder:text-outline focus:outline-none rounded-xl" id="adminEmail" placeholder="admin@adoptly.org" required="" type="email" value="ops-lead@adoptly.org"></div></div><div class="flex flex-col gap-2 text-left"><div class="flex items-center justify-between"><label class="font-label-md text-sm uppercase tracking-wider text-[#221B1A] font-semibold" for="adminPassword">Password</label></div><div class="relative flex items-center bg-white border border-[#E3DBD5] rounded-xl focus-within:border-[#E05A4F] focus-within:ring-2 focus-within:ring-[#E05A4F]/20 transition-all"><div class="absolute left-4 text-[#E05A4F] flex items-center pointer-events-none"><span class="material-symbols-outlined text-[22px]">key</span></div><input class="w-full h-14 pl-12 pr-12 text-[#221B1A] bg-transparent font-body-md text-base placeholder:text-outline focus:outline-none rounded-xl" id="adminPassword" placeholder="••••••••••••••••" required="" type="password"><button aria-label="Toggle password visibility" class="absolute right-3 text-[#8A7976] hover:text-[#E05A4F] p-2 rounded-lg transition-colors" id="togglePasswordBtn" onclick="togglePasscodeVisibility()" type="button"><span class="material-symbols-outlined text-[22px] block" id="eyeIcon">visibility</span></button></div></div><div class="flex items-start gap-2 mt-1 select-none"><label class="relative flex items-center justify-center cursor-pointer mt-0.5"><input checked="" class="peer sr-only" id="trustStation" type="checkbox"><div class="w-5 h-5 bg-[#F2ECE7] border border-[#DBD2CB] rounded peer-checked:bg-[#E05A4F] peer-checked:border-[#E05A4F] peer-focus-visible:ring-2 peer-focus-visible:ring-[#E05A4F] flex items-center justify-center transition-colors"><span class="material-symbols-outlined text-white text-[15px] opacity-0 peer-checked:opacity-100 font-bold">check</span></div></label><label class="cursor-pointer font-body-md text-sm text-[#736360] leading-snug" for="trustStation">Remember this device</label></div><div class="mt-2 flex flex-col gap-4"><button class="w-full h-14 bg-[#E05A4F] hover:bg-[#c94a40] text-white font-headline-sm text-base uppercase tracking-wider rounded-xl flex items-center justify-center gap-2 transition-colors group shadow-md shadow-[#E05A4F]/25 active:scale-[0.99]" id="loginSubmitBtn" type="submit"><span class="font-semibold text-base" id="btnLabel">Log In</span><span class="material-symbols-outlined text-[20px] group-hover:translate-x-1 transition-transform">arrow_forward</span></button><div class="text-center pt-1"><a class="font-body-md text-sm text-[#736360] hover:text-[#E05A4F] transition-colors underline underline-offset-4 decoration-[#DFBFBB] hover:decoration-[#E05A4F]" href="#recovery-dialog" onclick="showAuditModal('Password reset instructions have been dispatched to authorized administrators.')">Forgot password?</a></div></div></form></div></div><div class="fixed bottom-6 right-6 z-50 pointer-events-none opacity-0 translate-y-4 transition-all duration-300 bg-inverse-surface text-inverse-on-surface px-4 py-3 rounded-xl shadow-lg flex items-center gap-2 max-w-sm border border-white/10" id="systemToast"><span class="material-symbols-outlined text-[#E05A4F] text-[20px]">info</span><div class="flex flex-col"><span class="font-label-sm text-label-sm uppercase tracking-wider font-bold text-white" id="toastTitle">System Broadcast</span><span class="font-body-sm text-body-sm text-inverse-on-surface/90 text-left" id="toastMessage">Default Notification</span></div></div></div>
<script>
  function togglePasscodeVisibility() {
    var passInput = document.getElementById('adminPassword');
    var icon = document.getElementById('eyeIcon');
    if (passInput.type === 'password') {
      passInput.type = 'text';
      icon.textContent = 'visibility_off';
    } else {
      passInput.type = 'password';
      icon.textContent = 'visibility';
    }
  }

  function triggerAuth() {
    var email = document.getElementById('adminEmail').value.trim();
    var password = document.getElementById('adminPassword').value.trim();
    var btn = document.getElementById('loginSubmitBtn');
    var label = document.getElementById('btnLabel');

    if (!email || !password) {
      showAuditModal('Input error: Master Administrator identity and keyphrase are mandatory.');
      return;
    }

    // Visual authentication simulation
    label.textContent = 'VERIFYING CREDENTIALS...';
    btn.classList.add('opacity-80', 'pointer-events-none');

    setTimeout(function() {
      label.textContent = 'AUTHENTICATED // REDIRECTING...';
      btn.classList.remove('bg-on-surface');
      btn.classList.add('bg-tertiary');
      showAuditModal('Token accepted. Establishing secure operator session for ' + email);
      setTimeout(function() { window.location.href = 'v1_dashboard.php'; }, 1200);
      setTimeout(function() {
        label.textContent = 'AUTHENTICATE &rarr;';
        btn.classList.remove('bg-tertiary', 'opacity-80', 'pointer-events-none');
        btn.classList.add('bg-on-surface');
      }, 2200);
    }, 900);
  }

  function triggerSSOHandshake() {
    showAuditModal('Initiating WebAuthn handshake. Insert your YubiKey or authenticate via hardware biometrics.');
  }

  function showAuditModal(msg) {
    var toast = document.getElementById('systemToast');
    var toastMsg = document.getElementById('toastMessage');
    toastMsg.textContent = msg;
    toast.classList.remove('translate-y-20', 'opacity-0', 'pointer-events-none');
    toast.classList.add('translate-y-0', 'opacity-100');

    setTimeout(function() {
      toast.classList.remove('translate-y-0', 'opacity-100');
      toast.classList.add('translate-y-20', 'opacity-0', 'pointer-events-none');
    }, 4500);
  }
</script></main><footer class="w-full bg-white/80 backdrop-blur-md border-t border-[#F2ECE7] py-space-md"><div class="w-full px-6 md:px-10 flex flex-col sm:flex-row items-center justify-between gap-space-sm"><div class="flex items-center gap-space-sm"><span class="font-label-sm text-label-sm text-[#8A7976] tracking-wider">© Adoptly Animal Shelter System</span></div><div class="flex items-center gap-space-lg text-secondary"></div></div></footer>


